static final class RangeStreamer<T>
implements Streamer<Integer>, IndexableSource<Integer>, EnumerableSource<Integer> {

    final int start;

    final int end;

    int current;

    RangeStreamer(int start, int end) {
        this.start = start;
        this.current = start - 1;
        this.end = end;
    }

    @Override
    public @NonNull CompletionStage<Boolean> next() {
        if (++current >= end) {
            return NEXT_FALSE;
        }
        return NEXT_TRUE;
    }

    @Override
    public @NonNull Integer current() {
        return current;
    }

    @Override
    public @NonNull CompletionStage<Void> finish() {
        current = end;
        return FINISHED;
    }

    @Override
    public Integer elementAt(long index) {
        return (int)(start + index);
    }

    @Override
    public long limit() {
        return end - start;
    }

    @Override
    public boolean nextSync() throws Throwable {
        if (++current >= end) {
            return false;
        }
        return true;
    }
}

