static final class RangeStreamer<T>
implements Streamer<Integer>, IndexableSource<Integer>, EnumerableSource<Integer> {

    final int start;

    final int count;

    // Number of items already emitted (0..count). Counting avoids computing the exclusive
    // end (start + count), which can overflow when the last element is Integer.MAX_VALUE.
    int emitted;

    int current;

    RangeStreamer(int start, int count) {
        this.start = start;
        this.count = count;
    }

    @Override
    public @NonNull CompletionStage<Boolean> next() {
        if (emitted >= count) {
            return NEXT_FALSE;
        }
        current = start + emitted;
        emitted++;
        return NEXT_TRUE;
    }

    @Override
    public @NonNull Integer current() {
        return current;
    }

    @Override
    public @NonNull CompletionStage<Void> finish() {
        emitted = count;
        return FINISHED;
    }

    @Override
    public Integer elementAt(long index) {
        return (int)(start + index);
    }

    @Override
    public long limit() {
        return count;
    }

    @Override
    public boolean nextSync() throws Throwable {
        if (emitted >= count) {
            return false;
        }
        current = start + emitted;
        emitted++;
        return true;
    }
}

